import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 5

def design(feats):
    # Check if any feature shows significant association with outcome
    p_values = []
    effects = []

    for i, fid in enumerate(feats.ids):
        x = feats.x[:, i]
        y = feats.y
        t_stat, p_val = stats.ttest_ind(x[y==1], x[y==0], equal_var=False)
        effect_size = np.mean(x[y==1]) - np.mean(x[y==0])
        p_values.append(p_val)
        effects.append(abs(effect_size))

    # If no feature is significantly associated, return empty design
    if all(p > 0.05 for p in p_values):
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Find top features by effect size among significant ones
    sig_indices = [i for i, p in enumerate(p_values) if p <= 0.05]
    if not sig_indices:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features based on effect size
    top_indices = sorted(sig_indices, key=lambda i: effects[i], reverse=True)[:MAX_DRIVERS]
    top_features = [feats.ids[i] for i in top_indices]

    # Check for correlations to avoid near-duplicates
    corr_pairs = [(i, j) for i in range(len(top_features)) 
                  for j in range(i+1, len(top_features)) 
                  if abs(np.corrcoef(feats.x[:, feats.column(top_features[i])], 
                                    feats.x[:, feats.column(top_features[j])])[0,1]) >= 0.6]

    # Remove correlated features, keeping the one with stronger effect
    if corr_pairs:
        keep = set(range(len(top_features)))
        for i, j in corr_pairs:
            if i in keep and j in keep:
                if effects[i] < effects[j]:
                    keep.remove(i)
                else:
                    keep.remove(j)
        top_features = [top_features[k] for k in sorted(keep)]

    # For stratum consistency check, fit model within each stratum
    strata_consistent = True
    if len(set(feats.stratum)) > 1:
        for stratum in set(feats.stratum):
            mask = np.array([s == stratum for s in feats.stratum])
            stratum_x = feats.x[mask]
            stratum_y = feats.y[mask]
            if len(np.unique(stratum_y)) == 2:  # Need both classes
                try:
                    lr = LogisticRegression(fit_intercept=True, solver='liblinear')
                    lr.fit(stratum_x[:, [feats.column(f) for f in top_features]], stratum_y)
                    # Check if coefficients are similar to overall
                except:
                    strata_consistent = False
                    break

    # Return final design
    if not strata_consistent:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Create loadings based on effect sizes for weighted score
    loadings = {}
    for i, fid in enumerate(top_features):
        x = feats.x[:, feats.column(fid)]
        y = feats.y
        effect = np.mean(x[y==1]) - np.mean(x[y==0])
        loadings[fid] = effect

    return Design(
        drivers=tuple(top_features[:MAX_DRIVERS]),
        columns=tuple(top_features),
        products=(),
        loadings=loadings
    )

